function radioClusters(towers, links) {
  const label = Array.from({ length: towers }, (_, i) => i);
  let changed = true;
  while (changed) {
    changed = false;
    for (const [a, b] of links) {
      const low = Math.min(label[a], label[b]);
      if (label[a] !== low || label[b] !== low) { label[a] = low; label[b] = low; changed = true; }
    }
  }
  return new Set(label).size;
}

function radioClusters(towers, links) {
  const parent = Array.from({ length: towers }, (_, i) => i);
  const size = new Array(towers).fill(1);
  const find = (x) => {
    while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; }
    return x;
  };
  let groups = towers;
  for (const [a, b] of links) {
    let ra = find(a), rb = find(b);
    if (ra === rb) continue;
    if (size[ra] < size[rb]) [ra, rb] = [rb, ra];
    parent[rb] = ra;
    size[ra] += size[rb];
    groups--;
  }
  return groups;
}
